// Query: flat with multiple joins
var q = from o in orders
        join c in customers on o.CustomerId equals c.Id
        join s in shippers on o.ShipperId equals s.Id
        select new { c.Name, s.Company, o.Total };

// Method: single join in a fluent chain
var m = orders.Join(customers, o => o.CustomerId, c => c.Id, (o, c) => new { c.Name, o.Total })
    .Where(x => x.Total > 100).Take(20).ToList();

var monthly = orders.Join(stats,
    o => new { o.Year, o.Month },
    s => new { s.Year, s.Month }, // identical shape required
    (o, s) => new { o.Id, s.Average });

// Non-equi (range) join: cross + filter
var bands = orders.SelectMany(_ => tiers)
    .Where(x => x.o.Total >= x.tier.Min && x.o.Total < x.tier.Max)
    .Select(x => new { x.o.Id, x.tier.Name });

// Self left-join: every employee, manager name if any
var org = from e in employees
          join m in employees on e.ManagerId equals m.Id into g
          from m in g.DefaultIfEmpty()
          select new { Employee = e.Name, Manager = m == null ? "(top)" : m.Name };

// EF preferred: navigation does the same
var via = await db.Employees.Select(e => new { e.Name, Manager = e.Manager!.Name }).ToListAsync(ct);

// Full outer via left + right-anti, then concat
var leftRows = from a in A
                 join b in B on a.K equals b.K into g
                 from b in g.DefaultIfEmpty()
                 select new { K = a.K, A = (int?)a.V, B = b == null ? (int?)null : b.V };
HashSet<int> matchedB = ...; // keys matched above (or recompute)
var rightOnly = B.Where(b => !leftKeys.Contains(b.K))
    .Select(b => new { K = b.K, A = (int?)null, B = (int?)b.V });
var full = leftRows.Concat(rightOnly).ToList();

// In-memory: comparer overload
var matches = users.Join(orders,
    u => u.Email, o => o.CustomerEmail,
    (u, o) => new { u.Name, o.Total },
    StringComparer.OrdinalIgnoreCase);

// Portable: normalize both sides identically
var portable = users.Join(orders,
    u => u.Email.Trim().ToUpperInvariant(),
    o => o.CustomerEmail.Trim().ToUpperInvariant(),
    (u, o) => new { u.Name, o.Total });

// Pipeline test: exact expected output, order included
List<int> actual = RunPipeline(input).ToList();
bool ok = actual.SequenceEqual(new List<int> { 2, 4, 6 });

// Order-insensitive: sort first
bool same = a.OrderBy(x => x.Id).Select(x => x.Id)
    .SequenceEqual(b.OrderBy(x => x.Id).Select(x => x.Id));

// Shrink before joining: filter + narrow both sides first
var activeUsers = users.Where(u => u.Active).Select(u => new { u.Id, u.Name });
var bigOrders = orders.Where(o => o.Total > 1000).Select(o => new { o.UserId, o.Total });
var result = activeUsers.Join(bigOrders, u => u.Id, o => o.UserId, (u, o) => new { u.Name, o.Total }).ToList();

// Source-side distinct page (one SQL trip):
List<int> page = await db.Orders
    .Select(o => o.CustomerId).Distinct()
    .OrderBy(id => id).Skip((p - 1) * 20).Take(20)
    .ToListAsync(ct);
int uniques = await db.Orders.Select(o => o.CustomerId).Distinct().CountAsync(ct);

// In-memory top-3 per customer:
var top = orders.GroupBy(o => o.CustomerId)
    .Select(g => new { Customer = g.Key, Latest = g.OrderByDescending(o => o.Date).Take(3).ToList() });

// SQL-side (EF lateral take, translatable):
var topDb = await db.Customers
    .Select(c => new { c.Name, Latest = db.Orders
        .Where(o => o.CustomerId == c.Id).OrderByDescending(o => o.Date).Take(3).ToList() })
    .ToListAsync(ct);
